// programme MODULES + LESSONS.
//
// SOURCE-OF-TRUTH STATUS (user-confirmed): the 10 narrative "SOURCE" BGCT
// handbooks under Digital_Marketing_Team/ are treated as FINAL_TRUTH content
// authority for this prototype. Every Module and Lesson below carries a
// `source` field citing the exact handbook + section it comes from. The
// governance layer around those handbooks (.skill.md files, validation
// queues, metadata registries, review/evidence templates) was consulted only
// to understand source status history, known conflicts, duplicate risk, and
// exclusions — never used to override the narrative content. See
// docs/digital-marketing-team-source-map.md and
// docs/digital-marketing-team-exclusions.md for the full record.
//
// SCOPE RULES APPLIED (all user-confirmed):
//  - Exactly 10 active modules: 1 Foundation + 7 P-Max + 2 Shopping.
//  - PMAX-005 (Budget Bleed Control) is EXCLUDED — no module, lesson, or quiz
//    question exists for it anywhere in this programme. See
//    docs/digital-marketing-team-exclusions.md.
//  - No numeric Customer Acquisition / "NCA" bid-cap value is ever stated,
//    anywhere in this programme, because the PMAX-003 source itself gives
//    three different figures (£1 / £0.10 / £0.15) across its own sections.
//    The concept is acknowledged where the workflow requires it; the number
//    is never taught or quizzed.
//  - SHOPPING-001's defective naming-convention worked example (which uses
//    the wrong ad-type token for a Shopping campaign) is excluded entirely —
//    not silently repaired, not taught as valid guidance.
//  - SHOPPING-002's disputed approval-metadata conflict (a governance-file
//    bookkeeping dispute, unrelated to the narrative handbook) is out of
//    scope; only the plain, undisputed "campaign stays Paused until approved"
//    rule is taught.
//  - Named individual staff (e.g. first names used as Owner/Validator roles
//    in the source handbooks) are replaced throughout with generic role
//    wording ("the designated approver", "the process owner"). Generic
//    escalation-team names already used by the sources (Ads Team Lead,
//    Technical Team, Account Manager, Creative Team, Management) are kept as-is.
//  - Real client/brand names, live URLs, internal file paths, and source
//    hashes found in the underlying source documents are never reproduced.

const PROGRAMME_ID = 'prog-digital-marketing-onboarding';

const module = (id, orderIndex, title, summary, estimatedMinutes, source, prerequisiteModuleIds) => ({
  id,
  programmeId: PROGRAMME_ID,
  orderIndex,
  title,
  summary,
  estimatedMinutes,
  prerequisiteModuleIds: prerequisiteModuleIds || [],
  // Digital Marketing Team requires NO team-leader / reviewer sign-off (user-confirmed requirement).
  requiresSignoff: false,
  status: 'FINAL_TRUTH',
  source,
});

const lesson = (id, moduleId, orderIndex, title, content, estimatedMinutes, source) => ({
  id,
  moduleId,
  orderIndex,
  title,
  content,
  estimatedMinutes,
  required: true,
  status: 'FINAL_TRUTH',
  source,
});

